# Test the logic path for single QuerySet (should be unchanged)
from collections import defaultdict

class MockModel:
    def __init__(self, name):
        self._meta = type('Meta', (), {'label': name})()
    def __str__(self):
        return 'MockModel'

class MockQuerySet:
    def __init__(self, model):
        self.model = model
        self._raw_delete_called = False

    def _raw_delete(self, using):
        self._raw_delete_called = True
        return 5  # Mock count

# Test single QuerySet path (no optimization needed)
model = MockModel('TestModel')
qs = MockQuerySet(model)
fast_deletes = [qs]

fast_deletes_by_model = defaultdict(list)
for queryset in fast_deletes:
    fast_deletes_by_model[queryset.model].append(queryset)

# Simulate the logic from our implementation
for model, querysets in fast_deletes_by_model.items():
    if len(querysets) == 1:
        # Single query path - should behave exactly as before
        count = querysets[0]._raw_delete(using='default')
        print(f'Single QuerySet: count={count}, _raw_delete_called={querysets[0]._raw_delete_called}')
    else:
        print(f'Multiple QuerySets: would be combined')

print('Single QuerySet path works correctly - behavior unchanged')
"

cd . && python -c "
from functools import wraps
from django.utils.decorators import method_decorator

def test_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Testing: {func.__name__}, {func.__module__}, {func.__doc__}')
        return func(*args, **kwargs)
    return wrapper

class TestClass:
    @method_decorator(test_decorator)
    def test_method(self):
        '''Test method documentation'''
        return 'success'

# Test the exact scenario from the issue
try:
    result = TestClass().test_method()
    print(f'PASS: {result}')
except Exception as e:
    print(f'FAIL: {e}')
"

