import requests

binary_data = u'ööö'.encode('utf-8')

methods = ['POST', 'PUT', 'PATCH']
for method in methods:
    try:
        func = getattr(requests, method.lower())
        response = func('http://httpbin.org/' + method.lower(), data=binary_data)
        print(f'{method} with binary UTF-8 data: SUCCESS (Status {response.status_code})')
    except Exception as e:
        print(f'{method} with binary UTF-8 data: FAILED - {e}')
"

cd ./ && python -c "
import requests
from requests.exceptions import InvalidURL

# Test normal URL still works
try:
    # This should work normally (though it will fail to connect, which is expected)
    requests.get('http://httpbin.org/', timeout=0.001)
except requests.exceptions.ConnectTimeout:
    print('✅ Normal URL handling still works (got expected timeout)')
except Exception as e:
    print('❌ Normal URL handling broken:', type(e).__name__, str(e))

# Test the specific case from the issue
try:
    requests.get('http://.example.com')
    print('❌ Should have raised InvalidURL')
except InvalidURL as e:
    print('✅ Issue case works:', str(e))
except Exception as e:
    print('❌ Wrong exception type:', type(e).__name__, str(e))

# Test related cases
test_cases = ['http://..example.com', 'https://.com', 'http://.']
for url in test_cases:
    try:
        requests.get(url)
        print(f'❌ {url}: Should have raised InvalidURL')
    except InvalidURL:
        print(f'✅ {url}: Correctly raises InvalidURL')
    except Exception as e:
        print(f'❌ {url}: Wrong exception:', type(e).__name__)
"

