# Quick verification that basic autodoc still works
import sys
sys.path.insert(0, '.')

from sphinx.ext.autodoc import DocstringSignatureMixin, py_ext_sig_re

# Test that the basic functionality still works as expected
class TestDocumenter(DocstringSignatureMixin):
    def __init__(self):
        self.objpath = ['test_method']
        self.directive = type('MockDirective', (), {
            'state': type('MockState', (), {
                'document': type('MockDocument', (), {
                    'settings': type('MockSettings', (), {'tab_width': 8})()
                })()
            })()
        })()
        self._docstrings = None

    def get_doc(self):
        if self._docstrings:
            return self._docstrings
        return [['test_method(self, arg1: int) -> str', '', 'Test method documentation.']]

# Test single signature (should maintain exact same behavior)
doc = TestDocumenter()
result = doc._find_signature()
print('Single signature test:', result)

# Test multiple signatures
doc._docstrings = [['test_method(self, arg1: int) -> str', 'test_method(self, arg1: float) -> bool', '', 'Multiple overloads.']]
result = doc._find_signature()
print('Multiple signature test - args:', repr(result[0]) if result else None)
print('Multiple signature test - retann:', repr(result[1]) if result else None)

print('✓ Basic functionality verification passed')
"

