import scipy.signal._spectral_py as sp
import inspect

# Get the source code of the _spectral_helper function in scipy
try:
    source = inspect.getsource(sp._spectral_helper)
    lines = source.split('\n')
    for i, line in enumerate(lines):
        if 'window' in line.lower() and 'sum' in line:
            print(f'Line {i}: {line}')
except:
    print('Could not find _spectral_helper in scipy')

# Let's try to find the welch function which might have the window correction
try:
    source = inspect.getsource(sp.welch)
    lines = source.split('\n')
    for i, line in enumerate(lines):
        if 'window' in line.lower() and 'sum' in line:
            print(f'Welch Line {i}: {line}')
except Exception as e:
    print(f'Error: {e}')
