import ast
from sphinx.pycode.ast import ast_parse

# Test parsing 'None'
try:
    tree = ast_parse('None')
    print('Successfully parsed None:', ast.dump(tree))
    for node in ast.walk(tree):
        print('Node type:', type(node).__name__)
        if hasattr(node, 'id'):
