import unicodedata
from sympy.core.alphabets import greeks

def U(name):
    try:
        return unicodedata.lookup(name)
    except KeyError:
        return None

GSUB = lambda letter: U('GREEK SUBSCRIPT SMALL LETTER %s' % letter.upper())

for gl in greeks:
    char = GSUB(gl)
    if char:
        print(f'{gl}: {char} (U+{ord(char):04X})')
    else:
        print(f'{gl}: None')
"

